CREATE     PROCEDURE [synapse_fo].[usp_Update_GENERALJOURNALENTRY]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:42
	Description: Update stored procedure for GENERALJOURNALENTRY from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTINGDATE] = stg.[ACCOUNTINGDATE],
		tgt.[ACKNOWLEDGEMENTDATE] = stg.[ACKNOWLEDGEMENTDATE],
		tgt.[BUDGETSOURCELEDGERENTRYPOSTED] = stg.[BUDGETSOURCELEDGERENTRYPOSTED],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CREATEDTRANSACTIONID] = stg.[CREATEDTRANSACTIONID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DOCUMENTDATE] = stg.[DOCUMENTDATE],
		tgt.[DOCUMENTNUMBER] = stg.[DOCUMENTNUMBER],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FISCALCALENDARPERIOD] = stg.[FISCALCALENDARPERIOD],
		tgt.[FISCALCALENDARYEAR] = stg.[FISCALCALENDARYEAR],
		tgt.[JOURNALCATEGORY] = stg.[JOURNALCATEGORY],
		tgt.[JOURNALNUMBER] = stg.[JOURNALNUMBER],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LEDGER] = stg.[LEDGER],
		tgt.[LEDGERENTRYJOURNAL] = stg.[LEDGERENTRYJOURNAL],
		tgt.[LEDGERPOSTINGJOURNAL] = stg.[LEDGERPOSTINGJOURNAL],
		tgt.[LEDGERPOSTINGJOURNALDATAAREAID] = stg.[LEDGERPOSTINGJOURNALDATAAREAID],
		--tgt.[LSN] = stg.[LSN],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[POSTINGLAYER] = stg.[POSTINGLAYER],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		--tgt.[SKS_EFTAP_ORIGPAYMVOUCH] = stg.[SKS_EFTAP_ORIGPAYMVOUCH],
		tgt.[SUBLEDGERVOUCHER] = stg.[SUBLEDGERVOUCHER],
		tgt.[SUBLEDGERVOUCHERDATAAREAID] = stg.[SUBLEDGERVOUCHERDATAAREAID],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TRANSFERID] = stg.[TRANSFERID]
	 FROM [synapse_fo].[GENERALJOURNALENTRY] tgt
		INNER JOIN [staging_fo].[GENERALJOURNALENTRY] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
